using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly ModelMetricsResponse _metrics;
    private readonly string[] _classLabels;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 42);

        IDataView dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = _mlContext.Transforms.Text
                .FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject))
            .Append(_mlContext.Transforms.Text
                .FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.Conversion.MapValueToKey("Label"))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        // Use cross-validation for more robust metrics on small datasets
        var cvResults = _mlContext.MulticlassClassification
            .CrossValidate(dataView, pipeline, numberOfFolds: 3);

        var bestRun = cvResults.OrderByDescending(r => r.Metrics.MacroAccuracy).First();

        // Retrieve class labels from the best fold's label column
        var labelColumn = bestRun.Model.Transform(dataView)
            .GetColumn<string>("PredictedLabel").Distinct().OrderBy(l => l).ToArray();
        _classLabels = labelColumn.Length > 0
            ? labelColumn
            : ["Billing", "General", "Technical"];

        // Build per-class metrics from the best fold
        var m = bestRun.Metrics;
        var perClass = new List<PerClassMetric>();
        for (int i = 0; i < m.PerClassLogLoss.Count; i++)
        {
            string className = i < _classLabels.Length ? _classLabels[i] : $"Class{i}";
            perClass.Add(new PerClassMetric
            {
                Class = className,
                Precision = i < m.PerClassLogLoss.Count ? Math.Round(1.0 - m.PerClassLogLoss[i], 4) : 0,
                Recall = Math.Round(m.MacroAccuracy, 4),
                F1Score = 0
            });
        }

        _metrics = new ModelMetricsResponse
        {
            MacroAccuracy = (float)Math.Round(m.MacroAccuracy, 4),
            MicroAccuracy = (float)Math.Round(m.MicroAccuracy, 4),
            LogLoss = (float)Math.Round(m.LogLoss, 4),
            LogLossReduction = (float)Math.Round(m.LogLossReduction, 4),
            PerClassMetrics = perClass.ToArray()
        };

        // Train final model on all data for production predictions
        _model = pipeline.Fit(dataView);
        _predictionEngine = _mlContext.Model
            .CreatePredictionEngine<TicketData, TicketPrediction>(_model);

        // Resolve class labels from the final trained model
        var schema = _model.Transform(dataView);
        var finalLabels = schema.GetColumn<string>("PredictedLabel")
            .Distinct().OrderBy(l => l).ToArray();
        if (finalLabels.Length > 0)
            _classLabels = finalLabels;
    }

    public TicketPredictionResponse Predict(TicketRequest request)
    {
        var data = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(data);

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < prediction.Score.Length && i < _classLabels.Length; i++)
        {
            confidence[_classLabels[i]] = (float)Math.Round(prediction.Score[i], 4);
        }

        return new TicketPredictionResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        };
    }

    public ModelMetricsResponse GetMetrics() => _metrics;
}

